css:
body :where([data-bz-node="pi"]) .bz-block{padding:0}
body :where([data-bz-node="pi"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="pi"]>.bz-container{padding-inline:0}

body [data-bz-node="pi"]{background:#fff;padding:90px 0}
body [data-bz-node="pi"]>.bz-container{max-width:var(--container)}
body [data-bz-node="pi-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;align-items:center}
body [data-bz-node="pi-copy"],body [data-bz-node="pi-media"]{grid-column:auto}
body [data-bz-node="pi-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:540px}
body [data-bz-node="pi-text"] .bz-text,body [data-bz-node="pi-text2"] .bz-text{max-width:540px;margin-top:22px}
body [data-bz-node="pi-text"] p,body [data-bz-node="pi-text2"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="pi-text"] p:last-child,body [data-bz-node="pi-text2"] p:last-child{margin:0}
body [data-bz-node="pi-sub"] h3{font:700 20px/1.2 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:34px 0 0;max-width:540px}
body [data-bz-node="pi-media"] figure{margin:0}
body [data-bz-node="pi-media"] img{width:100%;height:auto;border-radius:0}
@media (max-width:1100px){body [data-bz-node="pi"]{padding:64px 24px}body [data-bz-node="pi-row"]{grid-template-columns:1fr;gap:32px}body [data-bz-node="pi-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="pi"]{padding:48px 20px}body [data-bz-node="pi-h"] h2{font-size:26px}body [data-bz-node="pi-sub"] h3{font-size:17px;margin-top:28px}}
